package dev.raf.radar;
import android.content.*;import android.graphics.drawable.GradientDrawable;import android.os.SystemClock;import android.view.*;import android.widget.*;
import androidx.test.platform.app.InstrumentationRegistry;import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class WidgetAgeTest {
 @Test public void circleFitsThreeDigitsAndAgeNeverChangesBounds()throws Exception{Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();Store s=new Store(c);s.prefs.edit().clear().putBoolean("overlay",true).putBoolean("widgetUpdateTime",true).putLong("gpsAt",System.currentTimeMillis()).commit();ScreenTest.shell("appops set dev.raf.radar SYSTEM_ALERT_WINDOW allow");Overlay[] overlay={null};int[] bounds=new int[2];long success=System.currentTimeMillis()-12000;s.readings("me",Collections.singletonList(new Store.Reading("econom",999,null,success,"fixture")));
 try{main(()->{overlay[0]=new Overlay(c,s);overlay[0].refresh();});InstrumentationRegistry.getInstrumentation().waitForIdleSync();main(()->{LinearLayout root=root(overlay[0]);bounds[0]=root.getWidth();bounds[1]=root.getHeight();assertTrue(bounds[0]>0);assertEquals(bounds[0],bounds[1]);assertEquals(GradientDrawable.OVAL,((GradientDrawable)root.getBackground()).getShape());PriceText price=(PriceText)root.getChildAt(0);assertEquals("999",price.getText().toString());assertEquals(root.getHeight()/2f,(price.getTop()+price.getBottom())/2f,1);assertTrue(price.getPaint().measureText("999")<=price.getWidth()-price.getPaddingLeft()-price.getPaddingRight()+1);assertTrue(label(overlay[0]).getText().toString().matches("[0-9]+"));assertEquals(Gravity.CENTER,label(overlay[0]).getGravity());assertEquals(0x80FFFFFF,label(overlay[0]).getCurrentTextColor());});ScreenTest.capture("widget-no-plus-999");int[] screenRect=new int[4];main(()->{View price=root(overlay[0]).getChildAt(0);int[] xy=new int[2];price.getLocationOnScreen(xy);screenRect[0]=xy[0];screenRect[1]=xy[1];screenRect[2]=price.getWidth();screenRect[3]=price.getHeight();});android.graphics.Bitmap shot=InstrumentationRegistry.getInstrumentation().getUiAutomation().takeScreenshot();assertNotNull(shot);int visible=0;for(int y=Math.max(0,screenRect[1]);y<Math.min(shot.getHeight(),screenRect[1]+screenRect[3]);y++)for(int x=Math.max(0,screenRect[0]);x<Math.min(shot.getWidth(),screenRect[0]+screenRect[2]);x++){int color=shot.getPixel(x,y),red=android.graphics.Color.red(color),green=android.graphics.Color.green(color),blue=android.graphics.Color.blue(color);if(red>100&&red>green*1.5&&red>blue*1.2)visible++;}shot.recycle();assertTrue("Price must be visible on actual overlay screenshot",visible>50);
 for(int rub:new int[]{0,9,50,999,1250}){s.readings("me",Collections.singletonList(new Store.Reading("econom",rub,null,success,"fixture")));main(()->overlay[0].refresh());InstrumentationRegistry.getInstrumentation().waitForIdleSync();main(()->{assertEquals(bounds[0],root(overlay[0]).getWidth());assertEquals(bounds[1],root(overlay[0]).getHeight());TextView p=(TextView)root(overlay[0]).getChildAt(0);assertTrue("Value "+rub+" width="+p.getPaint().measureText(p.getText().toString())+" available="+(p.getWidth()-p.getPaddingLeft()-p.getPaddingRight()),p.getPaint().measureText(p.getText().toString())<=p.getWidth()-p.getPaddingLeft()-p.getPaddingRight()+1);});}
 main(()->{s.prefs.edit().putBoolean("widgetShowPlus",true).commit();s.readings("me",Collections.singletonList(new Store.Reading("econom",999,null,success,"fixture")));overlay[0].refresh();});InstrumentationRegistry.getInstrumentation().waitForIdleSync();main(()->{assertEquals("+999",((TextView)root(overlay[0]).getChildAt(0)).getText().toString());assertTrue(root(overlay[0]).getWidth()>bounds[0]);s.prefs.edit().putBoolean("widgetShowPlus",false).commit();overlay[0].refresh();});InstrumentationRegistry.getInstrumentation().waitForIdleSync();
 main(()->{s.prefs.edit().putBoolean("widgetUpdateTime",false).commit();overlay[0].refresh();});InstrumentationRegistry.getInstrumentation().waitForIdleSync();main(()->{assertEquals(View.GONE,label(overlay[0]).getVisibility());assertEquals(bounds[0],root(overlay[0]).getWidth());assertEquals(bounds[1],root(overlay[0]).getHeight());});
 main(()->{s.prefs.edit().putBoolean("widgetUpdateTime",true).putInt("scale",160).putInt("textScale",150).commit();overlay[0].refresh();});InstrumentationRegistry.getInstrumentation().waitForIdleSync();main(()->{assertTrue(root(overlay[0]).getWidth()>bounds[0]);assertEquals(root(overlay[0]).getWidth(),root(overlay[0]).getHeight());});
 s.readings("me",Collections.singletonList(new Store.Reading("econom",null,null,System.currentTimeMillis(),"fixture")));assertEquals(success,s.lastSuccessfulReading("me"));main(()->{s.prefs.edit().putInt("scale",100).putInt("textScale",100).commit();overlay[0].close();overlay[0]=new Overlay(c,new Store(c));overlay[0].refresh();});InstrumentationRegistry.getInstrumentation().waitForIdleSync();main(()->{assertEquals(bounds[0],root(overlay[0]).getWidth());assertTrue(label(overlay[0]).getText().toString().matches("[0-9]+"));});
 }finally{main(()->{if(overlay[0]!=null)overlay[0].close();});}}
 static void main(Runnable r){InstrumentationRegistry.getInstrumentation().runOnMainSync(r);}static LinearLayout root(Overlay o){try{java.lang.reflect.Field f=Overlay.class.getDeclaredField("root");f.setAccessible(true);return (LinearLayout)f.get(o);}catch(Exception e){throw new AssertionError(e);}}static TextView label(Overlay o){return (TextView)root(o).getChildAt(1);}
}
